'use strict';
const A=window.ATLAS;
const ASSET_ROOT=new URL('.',document.currentScript.src);
const assetUrl=path=>new URL(path,ASSET_ROOT).href;
const $=(s)=>document.querySelector(s);
const $$=(s)=>Array.from(document.querySelectorAll(s));
const esc=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={wave:'<path d="M2 12h3V6h3v12h3V3h3v18h3V9h3v6h2"/>',pipeline:'<rect x="2" y="8" width="5" height="8" rx="1"/><rect x="17" y="8" width="5" height="8" rx="1"/><path d="M7 12h10M12 4v16"/>',layers:'<path d="m3 8 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 18l9 5 9-5"/>',flow:'<path d="M3 18c4-14 7 4 11-10s5 3 7-5M3 22h18M3 2v20"/>',score:'<path d="M3 7h18M3 11h18M3 15h18M3 19h18M14 3v12"/><ellipse cx="11" cy="16" rx="3" ry="2"/>',train:'<path d="m12 3 10 5-10 5L2 8l10-5ZM5 10v7c4 3 10 3 14 0v-7M22 8v9"/>',flask:'<path d="M9 3h6M10 3v7L4 20c-.4.8 0 1 1 1h14c1 0 1.4-.2 1-1l-6-10V3M7 15h10"/>',book:'<path d="M12 5c-3-2-7-2-10 0v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-3-2-7-2-10 0Zm0 0v15"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',input:'<path d="M4 3h12l4 4v14H4V3Zm12 0v4h4M8 12h8M8 16h5"/>',brain:'<path d="M12 4C6-2 0 8 5 11c-6 5 2 14 7 8 5 6 13-3 7-8 5-3-1-13-7-7Zm0 0v15M5 11h4m6 0h4"/>',sliders:'<path d="M4 3v18M12 3v18M20 3v18M1 8h6m2 8h6m2-10h6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" aria-hidden="true">${paths[name]||paths.wave}</svg>`;};
const links=(ids)=>`<div class="source-links"><span>Read the source</span>${ids.map(id=>`<a href="${esc(A.sources[id].url)}" target="_blank" rel="noopener">${esc(A.sources[id].label)}</a>`).join('')}</div>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${text}</span>`;
const head=(num,title,desc,tag='')=>`<header class="page-head"><div class="eyebrow">${num} / RESEARCH ATLAS</div><div class="head-line"><h1>${title}</h1>${tag?badge(tag):''}</div><p>${desc}</p></header>`;
const navs=[['pipeline','pipeline','Pipeline atlas'],['representations','layers','Representations'],['flow','flow','Flow matching lab'],['compiler','score','Symbolic compiler'],['training','train','How it learns'],['experiment','flask','Your vocal experiment'],['roadmap','map','Research path'],['sources','book','Sources & glossary']];
const initialScore=`score "Yard study"
tempo 76
meter 4/4
key C
voice lead
note C4 0 1 lyric "Through"
note D4 1 1 lyric "the"
note E4 2 1 lyric "gate"
note G4 3 1 lyric "and"
note E4 4 1 lyric "down"
note D4 5 1 lyric "the"
note C4 6 2 lyric "walk"`;
const S={route:'pipeline',stage:0,tab:'intuition',mode:'text2music',planner:true,duration:30,repr:'latent',flow:{seed:42,steps:32,step:0,guidance:1,solver:'euler',task:'generate',turbo:false},score:initialScore,compiled:null,irView:'events',training:'base'};
let flowTimer=null, audioContext=null, audioNodes=[], playTimer=null;
const routeFromHash=()=>{const x=location.hash.slice(1).split('/');return {route:navs.some(n=>n[0]===x[0])?x[0]:'pipeline',stage:Math.min(5,Math.max(0,Number(x[1])||0))};};
function shell(){const r=routeFromHash();S.route=r.route;if(r.route==='pipeline')S.stage=r.stage;const current=navs.find(n=>n[0]===S.route);$('#app').innerHTML=`<div class="app-layout"><aside class="sidebar"><a class="brand" href="#pipeline">${icon('wave')}<span>Music Anatomy<small>MAESTRO RESEARCH</small></span></a><div><div class="nav-label">The generation stack</div><nav class="nav" aria-label="Research chapters">${navs.map((n,i)=>`${i===6?'<div class="nav-divider"></div>':''}<a href="#${n[0]}" class="${S.route===n[0]?'active':''}" ${S.route===n[0]?'aria-current="page"':''}>${icon(n[1])}${n[2]}</a>`).join('')}</nav></div><div class="sidebar-note"><strong>From sound to symbols.</strong>A working map of what we can inspect, what we can control, and what remains a research question.</div></aside><div class="mobile-nav-overlay"></div><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="menu-toggle" aria-label="Open chapter navigation">☰</button><span>ACE-Step 1.5</span><span aria-hidden="true">/</span><span>${current[2]}</span></div><div class="top-right"><small>Snapshot · 05 Oct 2026</small><a class="header-source" href="${A.sources.paper.url}" target="_blank" rel="noopener">Technical report</a></div></header><main id="main" class="main" tabindex="-1">${page()}<footer class="footer"><span>ACE-Step 1.5 · inspected code <a class="plain-link mono" href="https://github.com/ace-step/ACE-Step-1.5/tree/${A.rev}" target="_blank" rel="noopener">${A.rev.slice(0,7)}</a></span><span><a class="plain-link" href="https://htansetiawan.github.io/maestro/">Maestro home</a> · Documented implementation + research proposals</span></footer></main></div></div>`;
$('.menu-toggle').onclick=()=>{$('.sidebar').classList.toggle('open');$('.mobile-nav-overlay').classList.toggle('open');};$('.mobile-nav-overlay').onclick=()=>{$('.sidebar').classList.remove('open');$('.mobile-nav-overlay').classList.remove('open');};bind();}
function page(){return ({pipeline:pipelinePage,representations:representationsPage,flow:flowPage,compiler:compilerPage,training:trainingPage,experiment:experimentPage,roadmap:roadmapPage,sources:sourcesPage})[S.route]();}
function modeInfo(){const by={text2music:{title:'Text to music',note:S.planner?'Text conditions plus LM-generated 5 Hz codes guide the acoustic generator.':'Planner bypassed. Caption and lyrics directly condition acoustic generation.',source:S.planner?'LM-generated discrete hints':'Silence / empty source context'},lego:{title:'Add vocals · Lego',note:'Source piano is encoded as context. XL Base generates a complementary vocal layer. Planner is off for the recorded experiment.',source:'VAE-encoded piano context'},cover:{title:'Cover',note:'The inference route bypasses LM planning. Source audio is quantized into acoustic codes to guide a new rendering.',source:'Quantized source → detokenized hints'},repaint:{title:'Repaint',note:'The inference route bypasses LM planning. Source context and a time mask guide local regeneration.',source:'Source latent + interval mask'}};return by[S.mode];}
function pipelinePage(){const d=A.stages[S.stage],m=modeInfo();return `${head('01','From intention to sound.','Follow a signal through ACE-Step. Select a task, then inspect what each stage receives, computes, and hands to the next.','Documented architecture')}<div class="toolbar"><div class="segmented" role="group" aria-label="Generation task">${[['text2music','Text to music'],['lego','Add vocals'],['cover','Cover'],['repaint','Repaint']].map(([k,v])=>`<button data-mode="${k}" aria-pressed="${S.mode===k}">${v}</button>`).join('')}</div><label class="toggle"><input id="planner" type="checkbox" ${S.planner?'checked':''} ${['cover','repaint'].includes(S.mode)?'disabled':''}>LM planner ${['cover','repaint'].includes(S.mode)?'bypassed':''}</label></div><section class="pipeline-wrap" aria-label="ACE-Step inference pipeline"><div class="section-label"><strong>INFERENCE PATH</strong><span>Choose a stage to inspect</span></div><div class="pipeline">${A.stages.map((x,i)=>`<button class="node ${i===S.stage?'selected':''} ${i===1&&!S.planner?'bypassed':''}" data-stage="${i}" aria-pressed="${i===S.stage}"><div class="node-num"><span>0${i+1}</span><span class="node-icon">${icon(['input','brain','sliders','flow','layers','wave'][i])}</span></div><strong>${x.name}</strong><small>${i===1&&!S.planner?'LM bypassed':x.tag}</small></button>`).join('')}</div><p class="route-note">${m.note}</p></section><div class="trace-grid"><section class="inspector"><div class="inspector-heading"><div><div class="eyebrow">STAGE 0${S.stage+1}</div><h2>${d.title}</h2></div><div class="back-next"><button class="btn" id="prev" ${S.stage===0?'disabled':''}>Previous</button><button class="btn" id="next" ${S.stage===5?'disabled':''}>Next stage</button></div></div><p class="intro-copy">${d.summary}</p>${S.stage===1&&!S.planner?'<div class="info-line">This task path does not call the LM planner. Its internals are shown here for comparison; source-derived acoustic hints may still be used by the selected task.</div>':''}<div class="tabs" role="tablist" aria-label="Stage inspection">${[['intuition','Mechanism'],['tensor','Tensors & math'],['code','Code boundary'],['research','Research opportunity']].map(([k,v])=>`<button role="tab" id="tab-${k}" data-tab="${k}" aria-selected="${S.tab===k}" aria-controls="stage-detail" tabindex="${S.tab===k?0:-1}">${v}</button>`).join('')}</div><div id="stage-detail" role="tabpanel" aria-labelledby="tab-${S.tab}">${stageDetail(d)}</div>${links(d.refs)}</section><aside class="contract"><h3>Representation contract</h3><dl>${Object.entries(d.contract).map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}<dt>Current source route</dt><dd>${m.source}</dd></dl></aside></div><div class="bottom-insight">${icon('info')}<div><strong>The open system is the object of study.</strong> This atlas explains ACE-Step’s published implementation. It does not claim to reconstruct Suno’s private production architecture.</div></div>`;}
function stageDetail(d){if(S.tab==='intuition')return `<div class="concepts">${d.intuition.map(([h,p])=>`<div class="concept"><h4>${h}</h4><p>${p}</p></div>`).join('')}</div>`;if(S.tab==='tensor')return `<div class="code-panel"><div class="code-heading"><span>Shapes / equations</span><span>Approximate lengths before padding</span></div><pre>${esc(d.tensor)}</pre></div>`;if(S.tab==='code'){let example=d.code;if(S.stage===0)example=`GenerationParams(\n    task_type="${S.mode}",\n${S.mode==='lego'?'    instruction="Generate the VOCALS track based on the audio context:",\n':''}${S.mode!=='text2music'?'    src_audio="piano.wav",\n':''}    lyrics=lyrics,\n    caption=caption,\n    thinking=${S.planner?'True':'False'},\n${S.mode==='repaint'?'    repainting_start=20.0,\n    repainting_end=30.0,\n':''})`;return `<div class="code-panel"><div class="code-heading"><span>${S.stage===5?'Experiment logic':'API / implementation outline'}</span><span>Inspect the linked source for full context</span></div><pre>${esc(example)}</pre></div>`;}return `<div class="research-note">${badge('Proposed investigation','proposal')}<h3>Where to intervene</h3><p>${d.research}</p></div>`;}
function representationsPage(){return `${head('02','Four representations. Four contracts.','Change the duration to see how waveform samples, acoustic frames, discrete codes, and note events differ.')}<div class="grid-2"><section class="panel"><h3>The cost of a representation</h3><div class="control-row"><label for="duration">Audio duration</label><output id="duration-value">${S.duration} seconds</output></div><input class="range" id="duration" type="range" min="4" max="240" step="1" value="${S.duration}"><div class="stats" id="repr-stats"></div><p class="note space-top">Counts are illustrative for the inspected 48 kHz / 25 Hz / 5 Hz configuration. Sequence padding is omitted. Counting values is not measuring storage bitrate.</p></section><section class="panel"><h3>What does the representation look like?</h3><div class="segmented" role="group" aria-label="Representation view">${[['wave','PCM'],['latent','Latents'],['codes','Codes'],['notes','Events']].map(([k,v])=>`<button data-repr="${k}" aria-pressed="${S.repr===k}">${v}</button>`).join('')}</div><div class="viz-frame" id="repr-viz"></div><p class="viz-note" id="repr-note"></p></section></div><div class="table-card space-top table-scroll"><table><thead><tr><th>Object</th><th>Time scale</th><th>What it represents</th><th>Safe interpretation</th></tr></thead><tbody><tr><td>Stereo waveform</td><td>48 kHz / channel</td><td>Air-pressure-related sampled signal</td><td>Amplitude and time. Musical meaning needs analysis.</td></tr><tr><td>Continuous acoustic latent</td><td>25 Hz × 64 channels</td><td>Compressed waveform information</td><td>A decoder input, not 64 named musical attributes.</td></tr><tr><td>Discrete FSQ code</td><td>5 Hz · 64k possibilities</td><td>A quantized acoustic representation</td><td>Code identity has no declared pitch/chord name.</td></tr><tr><td>Symbolic event</td><td>Explicit onset / duration</td><td>Pitch, time, voice, articulation, lyric</td><td>A typed musical object that can be constrained and edited.</td></tr></tbody></table></div><div class="grid-2 space-top"><div class="panel"><h3>Recoverability is an empirical question</h3><p>A representation may contain enough information to predict pitch without having an independent pitch coordinate. Measure probe performance on held-out music, then measure causal intervention effects separately.</p></div><div class="panel"><h3>A score carries more than notes</h3><p>MIDI events record performance-oriented note data. A readable score also needs meter, voice/staff assignment, spelling, quantization, ties, rests, and phrase structure. Keep those decisions in an explicit representation.</p></div></div>${links(['model','config','vae','fsq','xml'])}`;}
function updateRepr(){const t=S.duration;$('#duration-value').textContent=`${t} seconds`;$('#repr-stats').innerHTML=[[(t*96000).toLocaleString(),'waveform values'],[(t*25).toLocaleString(),'64-channel latent frames'],[(t*5).toLocaleString(),'discrete code IDs']].map(([v,l])=>`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`).join('');let svg='',note='';if(S.repr==='wave'){svg=`<svg viewBox="0 0 500 160" role="img" aria-label="Illustrative waveform"><path d="M0 80H500" stroke="#ddd"/><path d="${Array.from({length:250},(_,i)=>`${i?'L':'M'}${i*2} ${80+Math.sin(i*2.1)*Math.sin(i*.07)*49}`).join(' ')}" fill="none" stroke="#555" stroke-width="1.3"/><text x="8" y="150" fill="#888" font-size="12">PCM amplitude / time</text></svg>`;note='Synthetic waveform illustration. Stereo PCM contains two sampled signals; this drawing shows one channel.';}else if(S.repr==='latent'){svg=`<svg viewBox="0 0 500 160" role="img" aria-label="Illustrative acoustic latent matrix">${Array.from({length:240},(_,i)=>`<rect x="${(i%30)*15+30}" y="${Math.floor(i/30)*14+15}" width="12" height="11" fill="rgb(${Math.round(80+160*(.5+.5*Math.sin(i*2.3)))},${Math.round(80+160*(.5+.5*Math.sin(i*2.3)))},${Math.round(80+160*(.5+.5*Math.sin(i*2.3)))})"/>`).join('')}<text x="30" y="150" fill="#888" font-size="12">Time frames × acoustic channels (subset)</text></svg>`;note='Illustrative matrix, not a tensor from ACE-Step. Channel brightness has no assigned meaning such as pitch or loudness.';}else if(S.repr==='codes'){svg=`<svg viewBox="0 0 500 160" role="img" aria-label="Illustrative discrete acoustic code sequence">${[417,25801,620,51004,9352,2318,998,45021].map((v,i)=>`<rect x="${i*59+10}" y="45" width="51" height="45" rx="4" fill="#eee" stroke="#ddd"/><text x="${i*59+35}" y="72" text-anchor="middle" fill="#555" font-family="monospace" font-size="11">${v}</text><text x="${i*59+35}" y="110" text-anchor="middle" fill="#999" font-size="10">${(i*.2).toFixed(1)}s</text>`).join('')}<text x="10" y="150" fill="#888" font-size="12">One illustrative ID per 200 ms</text></svg>`;note='Invented example IDs. Adjacent numerical values do not imply adjacent pitches or similar musical meanings.';}else{svg=`<svg viewBox="0 0 500 160" role="img" aria-label="Symbolic notes in a piano roll">${Array.from({length:7},(_,i)=>`<path d="M30 ${i*17+15}H485" stroke="#e1e1e1"/>`).join('')}${[60,62,64,67,64,62,60].map((p,i)=>`<rect x="${i*57+35}" y="${120-(p-60)*13}" width="${i===6?90:48}" height="10" rx="2" fill="#555"/>`).join('')}<text x="30" y="150" fill="#888" font-size="12">Explicit pitch, onset, duration, and lyric</text></svg>`;note='The hand-authored Yard study. These notes are symbolic events, not a transcription of your recorded piano.';}$('#repr-viz').innerHTML=svg;$('#repr-note').textContent=note;}
function flowPage(){return `${head('03','Watch the path from noise.','Step through a synthetic velocity field to understand sampling, guidance, and masks. The controls operate on a small numerical model in your browser.','Mathematical illustration')}<div class="grid-2"><section class="panel"><div class="lab-head"><h3>Sampling controls</h3><label class="toggle"><input id="turbo" type="checkbox" ${S.flow.turbo?'checked':''}>Turbo analogy</label></div><div class="control-row"><label for="flow-seed">Noise seed</label><input class="select" id="flow-seed" type="number" min="0" max="4294967295" value="${S.flow.seed}"></div><div class="control-row"><label for="flow-steps">Integration steps</label><select class="select" id="flow-steps" ${S.flow.turbo?'disabled':''}>${[8,16,32,50].map(n=>`<option ${S.flow.steps===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="control-row"><label for="solver">Numerical solver</label><select class="select" id="solver"><option value="euler" ${S.flow.solver==='euler'?'selected':''}>Euler · one field evaluation</option><option value="heun" ${S.flow.solver==='heun'?'selected':''}>Heun · two field evaluations</option></select></div><div class="control-row"><label for="guidance">Guidance strength</label><output id="guidance-value">${S.flow.guidance.toFixed(1)}</output></div><input class="range" id="guidance" type="range" min="1" max="9" step=".5" value="${S.flow.guidance}" ${S.flow.turbo?'disabled':''}><div class="control-row"><label for="flow-task">Mask example</label><select class="select" id="flow-task"><option value="generate" ${S.flow.task==='generate'?'selected':''}>Generate whole sequence</option><option value="repaint" ${S.flow.task==='repaint'?'selected':''}>Repaint middle interval</option></select></div><p class="note">The Turbo analogy fixes 8 steps and guidance 1. It illustrates the control policy, not a distilled neural model.</p></section><section class="panel"><div class="lab-head"><h3>Latent sequence projection</h3><span class="badge" id="flow-time"></span></div><div class="viz-frame" id="flow-viz"></div><div class="legend"><span>Current sequence</span><span class="dashed">Synthetic conditional target</span></div><div class="control-row"><label for="flow-progress">Trajectory step</label><output id="flow-progress-value"></output></div><input class="range" id="flow-progress" type="range" min="0" max="${S.flow.steps}" value="${S.flow.step}"><div class="actions flow-actions"><button class="btn primary" id="flow-play">${icon('play')}Animate</button><button class="btn" id="flow-step">One step</button><button class="btn" id="flow-reset">Reset</button></div><p class="viz-note space-top">A synthetic 96-value sequence drawn as a curve. This is neither an actual acoustic latent nor generated audio.</p></section></div><div class="grid-2 space-top"><div class="panel"><h3>ACE-Step Base’s time convention</h3><div class="flow-equation">zₜ = (1 − t)z_data + tε<br>v_target = ε − z_data<br>v_CFG = v_null + s(v_cond − v_null)<br>z_next = z + Δt · v_CFG<br>Δt &lt; 0 · noise at t=1 · data at t=0</div><p class="note space-top">The flow-matching loss trains a velocity predictor. The deployed field is learned; the browser example uses a hand-written field.</p></div><div class="panel"><h3>What to notice</h3><div class="concepts"><div class="concept"><h4>Seed changes the starting point</h4><p>Keep it fixed when isolating the effect of a conditioning edit.</p></div><div class="concept"><h4>Guidance can amplify distortion</h4><p>Stronger conditioning pressure does not enforce exact pitch or note timing.</p></div><div class="concept"><h4>Masks limit where edits act</h4><p>Here, values outside the interval are restored exactly. Real latent-to-waveform boundaries may still introduce artifacts.</p></div></div></div></div><details class="details"><summary>Inspect the browser field and its limits</summary><p>We integrate the nonlinear synthetic field below on a uniform decreasing-time schedule. The null target is 80% of the conditional target. This choice makes guidance visible; it is not a measurement of ACE-Step. Euler and Heun solve the same toy ODE. No learned weights, semantic codes, or waveform decoder are running here.</p><pre>v(z, t, target) = 4(z − target) + 0.25 sin(3z + t)\nv_CFG = v(z,t,0.8·target) + s[v(z,t,target) − v(z,t,0.8·target)]</pre></details>${links(['model','flow','inference'])}`;}
function rng(seed){let n=(seed>>>0)||123456789;return ()=>{n^=n<<13;n^=n>>>17;n^=n<<5;return (n>>>0)/4294967296;};}
function flowTrace(){const f=S.flow,r=rng(f.seed);const target=Array.from({length:96},(_,i)=>.55*Math.sin(i*.13)+.21*Math.sin(i*.47));let z=target.map(()=>((r()+r()+r())-1.5)*1.9);const inMask=(i)=>f.task!=='repaint'||(i>=29&&i<=66);z=z.map((v,i)=>inMask(i)?v:target[i]);const trace=[z.slice()];const vel=(x,t,i)=>{const fn=(a)=>4*(x-a)+.25*Math.sin(3*x+t);const vn=fn(target[i]*.8);return vn+f.guidance*(fn(target[i])-vn);};for(let k=0;k<f.steps;k++){const t=1-k/f.steps,dt=-1/f.steps;z=z.map((x,i)=>{if(!inMask(i))return target[i];const v=vel(x,t,i);if(f.solver==='heun'){const p=x+dt*v;return x+dt*.5*(v+vel(p,t+dt,i));}return x+dt*v;});trace.push(z.slice());}return {trace,target};}
function updateFlow(){const f=S.flow;const {trace,target}=flowTrace();f.step=Math.min(f.steps,f.step);const z=trace[f.step];const path=(vals)=>vals.map((v,i)=>`${i?'L':'M'}${i*5+12} ${115-v*40}`).join(' ');$('#flow-viz').innerHTML=`<svg viewBox="0 0 500 250" role="img" aria-label="Synthetic latent sampling trajectory at step ${f.step}">${f.task==='repaint'?'<rect x="156" y="20" width="188" height="191" fill="#eee"/>':''}${[35,75,115,155,195].map(y=>`<path d="M12 ${y}H488" stroke="#e5e5e5"/>`).join('')}<path d="${path(target)}" fill="none" stroke="#aaa" stroke-dasharray="4 4" stroke-width="1.5"/><path d="${path(z)}" fill="none" stroke="#242424" stroke-width="1.7"/><text x="12" y="238" font-size="12" fill="#888">Sequence position</text><text x="488" y="238" font-size="12" text-anchor="end" fill="#888">Illustrative units</text></svg>`;$('#flow-time').textContent=`t = ${(1-f.step/f.steps).toFixed(3)}`;$('#flow-progress-value').textContent=`${f.step} / ${f.steps}`;$('#flow-progress').max=f.steps;$('#flow-progress').value=f.step;$('#guidance-value').textContent=f.guidance.toFixed(1);}
function compilerPage(){return `${head('04','Make musical intent executable.','A small symbolic system: edit a melody, compile it to typed note events, inspect the notation, and export a real MIDI or MusicXML file.','Research prototype')}<div class="info-line">This lab demonstrates a proposed symbolic layer. It does not run ACE-Step or transcribe your piano. Its example melody is hand-authored.</div><div class="pass-list" aria-label="Compiler passes"><div class="pass">Source text</div><span>→</span><div class="pass">Parse & validate</div><span>→</span><div class="pass">Typed event IR</div><span>→</span><div class="pass">Timing & notation</div><span>→</span><div class="pass">MIDI / MusicXML</div></div><div class="compiler-layout"><section class="panel"><div class="lab-head"><h3>Musical source</h3><button class="btn" id="score-example">Restore example</button></div><label class="tiny" for="score-editor">Quarter-note beats · pitch names · lyric per note</label><textarea class="editor" id="score-editor" spellcheck="false">${esc(S.score)}</textarea><div class="actions space-top"><button class="btn primary" id="compile">Compile score</button><button class="btn" id="transpose-down">Transpose −1</button><button class="btn" id="transpose-up">Transpose +1</button></div><div id="compile-status" role="status" aria-live="polite"></div><p class="edit-note">Supported: one monophonic voice, major keys, quarter-note beat units, a sixteenth-note grid, up to 64 beats. Rests are inferred from gaps. Overlapping notes are rejected.</p></section><section class="panel"><div class="lab-head"><h3>Inspectable output</h3><span class="badge">Symbolic events</span></div><div class="staff-view" id="score-view"></div><div class="actions"><button class="btn" id="score-play">${icon('play')}Play notes</button><button class="btn" id="score-stop">${icon('stop')}Stop</button><button class="btn" id="export-midi">Export MIDI</button><button class="btn" id="export-xml">Export MusicXML</button></div><p class="edit-note">Playback uses a simple browser oscillator, not a generated singing voice. Exported MusicXML includes note durations, inferred rests, barlines, lyrics, and ties across measures.</p><div class="tabs" role="tablist" aria-label="Intermediate representation"><button role="tab" data-ir="events" aria-selected="${S.irView==='events'}" aria-controls="ir-output" id="ir-tab-events" tabindex="${S.irView==='events'?0:-1}">Event IR</button><button role="tab" data-ir="performance" aria-selected="${S.irView==='performance'}" aria-controls="ir-output" id="ir-tab-performance" tabindex="${S.irView==='performance'?0:-1}">Performance IR</button></div><div class="code-panel"><pre class="ir-code" id="ir-output" role="tabpanel" aria-labelledby="ir-tab-${S.irView}"></pre></div></section></div><div class="reading-block"><h2>A compiler boundary you can defend</h2><p>Give each representation its own type and invariants. The score owns pitches, rational durations, voices, and lyric assignments. The performance layer owns tempo mapping, expressive timing, dynamics, and articulation. The acoustic layer owns timbre and waveform detail. A renderer must declare which constraints it can actually honor.</p><div class="grid-2"><div class="panel"><h3>Audio → score</h3><p>Audio → source separation when needed → pitch/onset/offset estimates → uncertain note events → beat/tempo inference → quantization → voice assignment → enharmonic spelling → notation.</p><p class="note">Keep performance timing and confidence beside the score. Quantization should be a reviewable decision; mixed audio can admit multiple plausible transcriptions.</p></div><div class="panel"><h3>Score → audio</h3><p>Notation → typed event IR → expressive performance IR → deterministic synthesis or a trained symbolic conditioning adapter → acoustic latents / waveform.</p><p class="note">For ACE-Step, a direct score adapter is proposed research. Turning a score into a caption or reference recording provides weaker, indirect control.</p></div></div><h2>Contracts for a neural backend</h2><div class="table-card table-scroll"><table><thead><tr><th>Invariant</th><th>Symbolic enforcement</th><th>Acoustic verification</th></tr></thead><tbody><tr><td>Pitch identity</td><td>Explicit MIDI pitch / spelling</td><td>Recovered note pitches and voicing</td></tr><tr><td>Timing</td><td>Rational beat positions + tempo map</td><td>Onset/offset errors in seconds</td></tr><tr><td>Lyric placement</td><td>Syllable → note mapping</td><td>Alignment against sung audio</td></tr><tr><td>Protected accompaniment</td><td>Immutable source track</td><td>Sample comparison before final mix</td></tr><tr><td>Notation fidelity</td><td>Voices, measures, rests, ties</td><td>Musician review and round-trip event comparison</td></tr></tbody></table></div></div>${links(['xml','pitch','mt3','model'])}`;}
const keyMap={C:[0,0],G:[7,1],D:[2,2],A:[9,3],E:[4,4],B:[11,5],F:[5,-1],Bb:[10,-2],Eb:[3,-3],Ab:[8,-4],Db:[1,-5],Gb:[6,-6]};
function parsePitch(p){const m=p.match(/^([A-G])([#b]?)(-?\d)$/);if(!m)throw new Error(`Invalid pitch ${p}; use C4, F#4, or Bb3.`);const oct=Number(m[3]),alter=m[2]==='#'?1:m[2]==='b'?-1:0;const midi=(oct+1)*12+{C:0,D:2,E:4,F:5,G:7,A:9,B:11}[m[1]]+alter;if(midi<0||midi>127)throw new Error(`Pitch ${p} is outside MIDI range.`);return {name:p,step:m[1],alter,octave:oct,midi};}
function compileScore(source){const o={title:null,tempo:null,meter:null,key:null,voice:null,events:[]};const seen=new Set();const lines=source.split('\n');if(lines.length>90)throw new Error('The lab accepts up to 90 source lines.');for(let i=0;i<lines.length;i++){const l=lines[i].trim();if(!l||l.startsWith('#'))continue;try{let m;if((m=l.match(/^score "([^"\n]{1,80})"$/))){if(seen.has('score'))throw new Error('Duplicate score declaration.');o.title=m[1];seen.add('score');}else if((m=l.match(/^tempo (\d+(?:\.\d+)?)$/))){if(seen.has('tempo'))throw new Error('Duplicate tempo declaration.');o.tempo=Number(m[1]);if(o.tempo<30||o.tempo>240)throw new Error('Tempo must be 30–240 BPM.');seen.add('tempo');}else if((m=l.match(/^meter (\d+)\/(4|8)$/))){if(seen.has('meter'))throw new Error('Duplicate meter declaration.');o.meter=[Number(m[1]),Number(m[2])];if(o.meter[0]<2||o.meter[0]>12)throw new Error('Meter numerator must be 2–12.');seen.add('meter');}else if((m=l.match(/^key ([A-G](?:b|#)?)$/))){if(seen.has('key'))throw new Error('Duplicate key declaration.');if(!keyMap[m[1]])throw new Error('Use C, G, D, A, E, B, F, Bb, Eb, Ab, Db, or Gb major.');o.key=m[1];seen.add('key');}else if((m=l.match(/^voice ([a-zA-Z][\w-]{0,30})$/))){if(seen.has('voice'))throw new Error('This lab supports one voice.');o.voice=m[1];seen.add('voice');}else if((m=l.match(/^note ([A-G][#b]?-?\d) (\d+(?:\.\d+)?) (\d+(?:\.\d+)?)(?: lyric "([^"\n]{0,40})")?$/))){const onset=Number(m[2]),duration=Number(m[3]);if(duration<=0||onset+duration>64)throw new Error('Notes must have positive duration and end within 64 beats.');if(!Number.isInteger(onset*4)||!Number.isInteger(duration*4))throw new Error('Onsets and durations must lie on a 0.25-beat grid.');o.events.push({id:`n${o.events.length+1}`,pitch:parsePitch(m[1]),onsetBeats:onset,durationBeats:duration,lyric:m[4]||null,line:i+1});if(o.events.length>64)throw new Error('Maximum 64 notes.');}else throw new Error('Unknown syntax. Use the supported declarations or note PITCH ONSET DURATION lyric "word".');}catch(e){throw new Error(`Line ${i+1}: ${e.message}`);}}
for(const k of ['title','tempo','meter','key','voice'])if(o[k]===null)throw new Error(`Missing ${k==='title'?'score':k} declaration.`);if(!o.events.length)throw new Error('Add at least one note.');o.events.sort((a,b)=>a.onsetBeats-b.onsetBeats);for(let i=1;i<o.events.length;i++)if(o.events[i].onsetBeats<o.events[i-1].onsetBeats+o.events[i-1].durationBeats)throw new Error(`Line ${o.events[i].line}: overlapping notes in a monophonic voice.`);o.lengthBeats=Math.max(...o.events.map(e=>e.onsetBeats+e.durationBeats));o.beatsPerBar=o.meter[0]*4/o.meter[1];o.durationSeconds=o.lengthBeats*60/o.tempo;return o;}
function compileUI(){stopNotes();S.score=$('#score-editor').value;try{S.compiled=compileScore(S.score);$('#compile-status').className='success';$('#compile-status').textContent=`Compiled ${S.compiled.events.length} notes · ${S.compiled.lengthBeats} beats · ${S.compiled.durationSeconds.toFixed(2)} seconds. Source text → event IR → timing / notation.`;['score-play','export-midi','export-xml','transpose-up','transpose-down'].forEach(id=>$('#'+id).disabled=false);drawScore();updateIR();}catch(e){S.compiled=null;$('#compile-status').className='error';$('#compile-status').textContent=e.message;$('#score-view').innerHTML='<p class="note">Resolve the source error to inspect the compiled score.</p>';$('#ir-output').textContent='No valid intermediate representation.';['score-play','export-midi','export-xml','transpose-up','transpose-down'].forEach(id=>$('#'+id).disabled=true);}}
function updateIR(){if(!S.compiled)return;const o=S.compiled;let x;if(S.irView==='events')x={type:'ScoreEventIR',title:o.title,meter:o.meter.join('/'),key:o.key+' major',voice:o.voice,events:o.events.map(e=>({id:e.id,pitch:e.pitch.name,midi:e.pitch.midi,onsetBeats:e.onsetBeats,durationBeats:e.durationBeats,lyric:e.lyric}))};else x={type:'PerformanceIR',tempoBpm:o.tempo,timingPolicy:'Exact beat-to-second mapping; no humanization',events:o.events.map(e=>({id:e.id,midi:e.pitch.midi,onsetSeconds:+(e.onsetBeats*60/o.tempo).toFixed(4),durationSeconds:+(e.durationBeats*60/o.tempo).toFixed(4),velocity:80,frequencyHz:+(440*2**((e.pitch.midi-69)/12)).toFixed(2)}))};$('#ir-output').textContent=JSON.stringify(x,null,2);}
function drawScore(){const o=S.compiled,w=Math.max(600,o.lengthBeats*63+90),x=b=>76+b*60,y=p=>94-(({C:0,D:1,E:2,F:3,G:4,A:5,B:6}[p.step])+(p.octave-4)*7)*5;let marks='';for(let b=0;b<=o.lengthBeats;b+=o.beatsPerBar){marks+=`<path d="M${x(b)} 44V84" stroke="#aaa"/><text x="${x(b)+5}" y="27" fill="#aaa" font-size="11">${Math.floor(b/o.beatsPerBar)+1}</text>`;}for(const e of o.events){const px=x(e.onsetBeats)+15,py=y(e.pitch);let ledgers='';if(py>=94)for(let yy=94;yy<=py;yy+=10)ledgers+=`<path d="M${px-12} ${yy}h24" stroke="#777"/>`;if(py<=34)for(let yy=34;yy>=py;yy-=10)ledgers+=`<path d="M${px-12} ${yy}h24" stroke="#777"/>`;marks+=`${ledgers}<ellipse cx="${px}" cy="${py}" rx="7" ry="5" transform="rotate(-20 ${px} ${py})" fill="${e.durationBeats>=2?'white':'#333'}" stroke="#333" stroke-width="1.5"/><path d="M${px+6} ${py}V${py-30}" stroke="#333" stroke-width="1.5"/>${e.pitch.alter?`<text x="${px-19}" y="${py+5}" font-size="17">${e.pitch.alter>0?'♯':'♭'}</text>`:''}<text x="${px}" y="135" text-anchor="middle" fill="#666" font-size="12">${esc(e.lyric||'')}</text><text x="${px}" y="158" text-anchor="middle" fill="#aaa" font-size="10">${esc(e.pitch.name)} · ${e.durationBeats}b</text>`;}
$('#score-view').innerHTML=`<svg width="${w}" height="178" viewBox="0 0 ${w} 178" role="img" aria-label="Event-aligned notation sketch of ${esc(o.title)}">${[44,54,64,74,84].map(yy=>`<path d="M12 ${yy}H${w-10}" stroke="#ccc"/>`).join('')}<text x="18" y="85" font-size="47" fill="#555">𝄞</text><text x="53" y="60" font-size="18">${o.meter[0]}</text><text x="53" y="81" font-size="18">${o.meter[1]}</text>${marks}</svg><div class="tiny">Event-aligned notation sketch · full rests, key signature, and ties are in the MusicXML export.</div>`;}
function transpose(delta){if(!S.compiled)return;const names=['C','Db','D','Eb','E','F','Gb','G','Ab','A','Bb','B'];const o=S.compiled;try{for(const e of o.events)if(e.pitch.midi+delta<0||e.pitch.midi+delta>127)throw new Error('Transposition would exceed the MIDI pitch range.');S.score=$('#score-editor').value.replace(/^note ([A-G][#b]?-?\d)/gm,(_,p)=>{const n=parsePitch(p).midi+delta;return `note ${names[n%12]}${Math.floor(n/12)-1}`;}).replace(/^key ([A-G][b#]?)/gm,()=>`key ${names[(keyMap[o.key][0]+delta+12)%12]}`);$('#score-editor').value=S.score;compileUI();}catch(e){$('#compile-status').className='error';$('#compile-status').textContent=e.message;}}
function stopNotes(){if(playTimer)clearTimeout(playTimer);playTimer=null;for(const node of audioNodes)try{node.stop();}catch{}audioNodes=[];if($('#score-play'))$('#score-play').disabled=!S.compiled;}
async function playNotes(){if(!S.compiled)return;stopNotes();try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();const o=S.compiled,base=audioContext.currentTime+.08;for(const e of o.events){const osc=audioContext.createOscillator(),gain=audioContext.createGain();const start=base+e.onsetBeats*60/o.tempo,len=e.durationBeats*60/o.tempo;osc.type='triangle';osc.frequency.value=440*2**((e.pitch.midi-69)/12);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.15,start+.012);gain.gain.exponentialRampToValueAtTime(.03,start+Math.max(.02,len-.045));gain.gain.linearRampToValueAtTime(0,start+len);osc.connect(gain);gain.connect(audioContext.destination);osc.start(start);osc.stop(start+len+.03);audioNodes.push(osc);}$('#score-play').disabled=true;playTimer=setTimeout(stopNotes,(o.durationSeconds+.2)*1000);}catch(e){$('#compile-status').className='error';$('#compile-status').textContent='Audio playback could not start in this browser. MIDI and MusicXML export remain available.';}}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function vlq(n){let bytes=[n&127];while((n>>=7)>0)bytes.unshift((n&127)|128);return bytes;}
function exportMidi(){const o=S.compiled;if(!o)return;const ppq=480,events=[];const text=(str)=>Array.from(new TextEncoder().encode(str));const meta=(tick,type,str)=>{const b=text(str);events.push({tick,order:0,bytes:[255,type,...vlq(b.length),...b]});};const tempo=Math.round(60000000/o.tempo);events.push({tick:0,order:0,bytes:[255,81,3,(tempo>>16)&255,(tempo>>8)&255,tempo&255]},{tick:0,order:0,bytes:[255,88,4,o.meter[0],Math.log2(o.meter[1]),o.meter[1]===8&&o.meter[0]%3===0?36:24,8]},{tick:0,order:0,bytes:[255,89,2,keyMap[o.key][1]&255,0]},{tick:0,order:0,bytes:[192,0]});meta(0,3,o.title);for(const e of o.events){const tick=Math.round(e.onsetBeats*ppq);if(e.lyric)meta(tick,5,e.lyric);events.push({tick,order:2,bytes:[144,e.pitch.midi,80]},{tick:Math.round((e.onsetBeats+e.durationBeats)*ppq),order:1,bytes:[128,e.pitch.midi,0]});}events.sort((a,b)=>a.tick-b.tick||a.order-b.order);let t=0,track=[];for(const e of events){track.push(...vlq(e.tick-t),...e.bytes);t=e.tick;}track.push(0,255,47,0);const be32=(n)=>[(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];const bytes=new Uint8Array([...text('MThd'),0,0,0,6,0,0,0,1,(ppq>>8)&255,ppq&255,...text('MTrk'),...be32(track.length),...track]);download(bytes,'yard-study.mid','audio/midi');}
function exportXML(){const o=S.compiled;if(!o)return;const xe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const divisions=4,barTicks=o.beatsPerBar*divisions,total=Math.ceil(o.lengthBeats/o.beatsPerBar)*barTicks;let pieces=[],cursor=0;for(const e of o.events){const start=e.onsetBeats*divisions,len=e.durationBeats*divisions;if(start>cursor)pieces.push({start:cursor,length:start-cursor,rest:true});pieces.push({start,length:len,e});cursor=start+len;}if(cursor<total)pieces.push({start:cursor,length:total-cursor,rest:true});const measures=Array.from({length:total/barTicks},()=>[]);for(const p of pieces){let s=p.start,left=p.length;while(left>0){const m=Math.floor(s/barTicks),n=Math.min(left,barTicks-s%barTicks);const before=s>p.start,after=n<left;let body;if(p.rest)body=`<note><rest/><duration>${n}</duration><voice>1</voice></note>`;else{const e=p.e;body=`<note><pitch><step>${e.pitch.step}</step>${e.pitch.alter?`<alter>${e.pitch.alter}</alter>`:''}<octave>${e.pitch.octave}</octave></pitch><duration>${n}</duration>${before?'<tie type="stop"/>':''}${after?'<tie type="start"/>':''}<voice>1</voice>${before||after?`<notations>${before?'<tied type="stop"/>':''}${after?'<tied type="start"/>':''}</notations>`:''}${!before&&e.lyric?`<lyric number="1"><syllabic>single</syllabic><text>${xe(e.lyric)}</text></lyric>`:''}</note>`;}measures[m].push(body);s+=n;left-=n;}}
const attrs=`<attributes><divisions>${divisions}</divisions><key><fifths>${keyMap[o.key][1]}</fifths><mode>major</mode></key><time><beats>${o.meter[0]}</beats><beat-type>${o.meter[1]}</beat-type></time><clef><sign>G</sign><line>2</line></clef></attributes><direction placement="above"><direction-type><metronome><beat-unit>quarter</beat-unit><per-minute>${o.tempo}</per-minute></metronome></direction-type><sound tempo="${o.tempo}"/></direction>`;
const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE score-partwise PUBLIC "-//Recordare//DTD MusicXML 4.0 Partwise//EN" "http://www.musicxml.org/dtds/partwise.dtd">\n<score-partwise version="4.0"><work><work-title>${xe(o.title)}</work-title></work><part-list><score-part id="P1"><part-name>${xe(o.voice)}</part-name></score-part></part-list><part id="P1">${measures.map((m,i)=>`<measure number="${i+1}">${i===0?attrs:''}${m.join('')}${i===measures.length-1?'<barline location="right"><bar-style>light-heavy</bar-style></barline>':''}</measure>`).join('')}</part></score-partwise>`;download(xml,'yard-study.musicxml','application/vnd.recordare.musicxml+xml');}
function trainingPage(){const variant={base:{title:'Base / XL Base',copy:'The flexible pretrained branch supports the broad task set, including extraction, Lego layering, and completion. It supports classifier-free guidance. Your local vocal take used XL Base.',steps:'50 in your run',cfg:'Supported',tasks:'Text, cover, repaint, extract, Lego, complete'},sft:{title:'SFT / XL SFT',copy:'Supervised fine-tuning emphasizes alignment and audio quality. In the pinned model zoo, SFT supports text-to-music, cover, and repaint; it does not expose the Base-only extraction, Lego, and completion task set.',steps:'50 listed',cfg:'Supported',tasks:'Text, cover, repaint'},turbo:{title:'Turbo / XL Turbo',copy:'Distillation reduces the number of sampling steps. The pinned model zoo lists eight steps; the inference handler sets guidance to 1.0 for Turbo. Fewer steps are a property of a trained checkpoint, not a general replacement for Base sampling.',steps:'8 listed',cfg:'No ordinary CFG',tasks:'Text, cover, repaint'}}[S.training];return `${head('05','The inference graph has a history.','Separate the training of a representation, an acoustic generator, and a planner. Then distinguish model capability from the controls exposed at inference.')}<div class="grid-2"><section class="panel"><h3>Training objectives by component</h3><div class="concepts"><div class="concept"><h4>Waveform autoencoder</h4><p>Learn a compact acoustic representation and waveform reconstruction. Reconstruction quality bounds what later generation can reproduce.</p></div><div class="concept"><h4>Acoustic tokenizer</h4><p>Pool acoustic features and quantize with FSQ. Discrete code IDs create an autoregressive vocabulary; they do not become a music-theory ontology.</p></div><div class="concept"><h4>DiT</h4><p>Fit conditional flow velocities on noised acoustic latents. Task-specific source and mask configurations teach different transformations.</p></div><div class="concept"><h4>Language model</h4><p>Learn conditional token sequences for metadata, text, and acoustic codes. Autoregressive loss and acoustic flow loss solve different problems.</p></div></div>${links(['model','lm','vae'])}</section><section class="panel"><h3>Checkpoint behavior</h3><div class="segmented" role="group" aria-label="Model family">${[['base','Base'],['sft','SFT'],['turbo','Turbo']].map(([k,v])=>`<button data-training="${k}" aria-pressed="${S.training===k}">${v}</button>`).join('')}</div><h3 class="space-top">${variant.title}</h3><p>${variant.copy}</p><div class="contract" style="border:0;padding:0"><dl><dt>Sampling</dt><dd>${variant.steps}</dd><dt>Guidance</dt><dd>${variant.cfg}</dd><dt>Tasks listed in pinned model zoo</dt><dd>${variant.tasks}</dd></dl></div><p class="note space-top">The paper describes the original ~2B DiT. The repository’s later XL family scales the DiT decoder to ~4B. Keep checkpoint and code revisions attached to measurements.</p>${links(['tutorial','inference'])}</section></div><div class="reading-block"><h2>The paper’s progressive recipe</h2><div class="timeline"><div class="timeline-item"><div class="timeline-num"><span>1</span></div><div class="timeline-copy"><h3>Generative pretraining</h3><p>The report describes 20M samples with silence as source to learn acoustic and musical priors.</p></div></div><div class="timeline-item"><div class="timeline-num"><span>2</span></div><div class="timeline-copy"><h3>Omni-task mixture</h3><p>17M samples vary source and mask conditions for generation and editing.</p></div></div><div class="timeline-item"><div class="timeline-num"><span>3</span></div><div class="timeline-copy"><h3>High-fidelity SFT</h3><p>A curated 2M subset emphasizes alignment between controls and outputs.</p></div></div><div class="timeline-item"><div class="timeline-num"><span>4</span></div><div class="timeline-copy"><h3>Distillation</h3><p>Adversarial dynamic-shift distillation produces a short-step student. This changes the trained velocity model, not merely the sampler’s step count.</p></div></div></div><div class="callout"><p>The report also proposes intrinsic alignment: lyric-attention-derived rewards for DiT, and composer/listener consistency rewards for the LM. Its main evaluation table explicitly uses a distilled DiT without RL. A paper’s training proposal does not establish that a downloaded checkpoint underwent that stage.</p></div>${links(['paper'])}<h2>Your fine-tuning experiment should answer one question</h2><p>For an interpretable score adapter, first hold the codec and acoustic backbone fixed. Align symbolic events with audio latents, train a conditioning path, and evaluate pitch/onset preservation against a stock source-conditioned baseline. Training for a preferred timbre and training for exact note control are different objectives.</p><details class="details"><summary>Plan an ablation before changing model weights</summary><div class="table-scroll"><table><thead><tr><th>Run</th><th>Condition</th><th>What it tests</th></tr></thead><tbody><tr><td>Baseline</td><td>Caption + lyrics</td><td>Unconstrained melodic invention</td></tr><tr><td>Source context</td><td>Baseline + source piano</td><td>Indirect musical adherence</td></tr><tr><td>Symbolic adapter</td><td>Baseline + note event encoder</td><td>Explicit pitch / timing control</td></tr><tr><td>Adapter + source</td><td>Both conditions</td><td>Complementarity and interference</td></tr></tbody></table></div><p class="note space-top">Use held-out melodies, multiple matched seeds, and independently computed musical metrics. Do not interpret ASR word recovery as a pitch-alignment score.</p></details></div>`;}
function experimentPage(){return `${head('06','A good voice. An uncertain melody.','Trace your actual piano-and-vocal take through the model, then locate the missing musical constraints.','Recorded experiment')}<section class="panel"><div class="lab-head"><div><h3>The Yard · piano and voice</h3><span class="tiny">Original piano + ACE-Step XL Base vocal layer · 04 Oct 2026</span></div><span class="badge">94.976 seconds</span></div><audio class="experiment-player" controls preload="metadata" src="${assetUrl('audio/yard-piano-and-voice.mp3')}">Your browser does not support audio playback.</audio><div class="stats experiment-stats"><div class="stat"><strong>XL Base</strong><span>checkpoint family</span></div><div class="stat"><strong>50 / 7.0</strong><span>steps / guidance</span></div><div class="stat"><strong>Off</strong><span>LM + all CoT flags</span></div><div class="stat"><strong>20261004</strong><span>fixed generation seed</span></div></div></section><div class="grid-2 space-top"><section class="panel"><h3>Generated vocal stem</h3><p>ACE-Step generated singing from supplied lyrics and source piano context. No prerecorded vocal sample was selected.</p><audio class="experiment-player" controls preload="metadata" src="${assetUrl('audio/vocals.mp3')}"></audio><p class="note space-top">This player uses an MP3 listening copy of the recorded float32 WAV. No retiming or pitch correction has been added.</p></section><section class="panel"><h3>What the model was asked</h3><div class="code-panel"><pre>task_type: lego\ntrack: VOCALS\nsource: your piano audio\nvoice: warm expressive male tenor\nlyrics: two verses + chorus + outro\nbpm: not supplied\nkey / meter: not supplied\nexplicit notes / syllable timing: absent</pre></div></section></div><div class="reading-block"><h2>The actual signal path</h2><div class="timeline">${[['Piano + lyric text','Audio from st_elmo_fire.m4a was extracted. Lyrics described the Yard and red brick buildings. No melody transcription or syllable-to-note assignment was created.'],['LM bypassed','thinking=False; all CoT flags disabled; audio_codes empty. The source-conditioning route still processed the supplied piano.'],['XL Base generates a vocal layer','The source audio served as context for the Lego VOCALS task. The model inferred its own vocal phrase entrances and notes.'],['Stem mixed with unchanged piano','The vocal gain was 0.58892416759623. Sixteen milliseconds of silence were appended for length matching. There was no time stretching or piano regeneration.'],['Checks establish signal and word presence','The audio was finite and non-silent with no clipped mix peaks. Whisper recognized much of the lyric text, with errors and repetitions. The final outro line was absent from that transcription.']].map(([h,p],i)=>`<div class="timeline-item"><div class="timeline-num"><span>${i+1}</span></div><div class="timeline-copy"><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div><div class="callout"><p><strong>Your listening observation:</strong> voice quality was promising, while melody following and alignment were weak. The saved checks did not measure these properties. The run left pitches and phrase timing to inference; the record alone cannot isolate every cause of the mismatch.</p></div><h2>Turn that observation into an experiment</h2><div class="table-card table-scroll"><table><thead><tr><th>Question</th><th>Measurement</th><th>Change to test</th></tr></thead><tbody><tr><td>Did it sing the intended melody?</td><td>Vocal note pitches vs. annotated target line</td><td>Explicit melody / score conditioning</td></tr><tr><td>Did syllables land in the right places?</td><td>Word and syllable onset error</td><td>Aligned lyric-to-note events</td></tr><tr><td>Did entrances respect piano phrasing?</td><td>Phrase timing against annotated piano performance</td><td>Phrase boundaries + performance tempo map</td></tr><tr><td>Did accompaniment remain intact?</td><td>Verify retained source samples before mixing</td><td>Preserve original stem through a fixed mix path</td></tr></tbody></table></div><div class="actions space-top"><a class="btn primary" href="#pipeline/0" id="trace-experiment">Inspect this task in the atlas</a><a class="btn" href="#compiler">Try the symbolic layer</a></div></div>${links(['experiment','inference','model'])}`;}
function roadmapPage(){return `${head('07','A path from inspection to invention.','Build an evidence trail at each representation boundary. Each investigation produces an artifact you can inspect, compare, and reuse.')}<div class="reading-block"><div class="callout"><p>The central research question: can a symbolic intermediate representation preserve musical authorship while a learned acoustic backend supplies sound and expression?</p></div>${A.lessons.map((l,i)=>`<details class="details" ${i===0?'open':''}><summary>${l.title}</summary><div class="lesson"><span class="badge">0${i+1}</span><div><h3>${l.question}</h3><p>${l.text}</p><div class="deliver">Deliverable: ${l.deliver}</div>${links(l.refs)}</div></div></details>`).join('')}<h2>Evaluate the two directions independently</h2><div class="table-card table-scroll"><table><thead><tr><th>Direction</th><th>Core measurements</th><th>Failure to inspect</th></tr></thead><tbody><tr><td>Audio → events</td><td>Note precision/recall; onset/offset error; pitch bend; instrument/voice assignment</td><td>Overlapping harmonics, sustain, missing quiet notes</td></tr><tr><td>Events → notation</td><td>Quantization, meter, spelling, rest/tie correctness; musician edit effort</td><td>Readable-but-wrong structure, ambiguous voices</td></tr><tr><td>Score → performance</td><td>Event preservation; tempo mapping; expressive timing and dynamics</td><td>Humanization changing the intended rhythm</td></tr><tr><td>Performance → audio</td><td>Pitch/onset fidelity; timbre; artifacts; lyric alignment</td><td>Good sound with incorrect notes</td></tr></tbody></table></div><h2>Make round trips preserve meaning</h2><p>Audio → score → audio is generally not waveform identity: notation omits room acoustics, microphone placement, and many performance details. Specify which invariants must survive. Store uncertainty and the original performance so musicians can revise inferred structure without losing the evidence.</p><details class="details"><summary>Minimal experimental record</summary><pre>source audio hash / license / provenance\ncode + model revisions\ncaption, lyrics, source and reference roles\nseed, sampler, schedule, guidance, task mask\nwaveform → latent → codes → events snapshots\nscore hypotheses + confidence + alignment\nindependent musical metrics + listening notes</pre></details></div>${links(['pitch','mt3','xml','model'])}`;}
function sourcesPage(){const descriptions={tutorial:'Developer explanation of the optional planner, source conditioning, and model families. Pinned to the code used for your experiment.',inference:'Task semantics, GenerationParams, CoT flags, checkpoint-specific controls, and export formats.',model:'Inspect prepare_condition, tokenize / detokenize, flow loss, and generate_audio in the XL Base implementation.',config:'FSQ levels, pooling, acoustic channels, encoder widths, and model configuration definitions.',embed:'Separate caption hidden-state inference and lyric embedding lookup.',lm:'Autoregressive metadata and acoustic-code generation plumbing.',vae:'Waveform encoder / decoder structure. The local downloaded VAE config, rather than MLX constructor defaults, supplies the 25 Hz calculations in this atlas.',training:'Fine-tuning loop for parameter-efficient adaptation; not proof that any particular checkpoint received every paper training stage.',paper:'Technical report v3. Distinguish reported training and alignment proposals from released checkpoint provenance.',flow:'The general conditional flow-matching framework underlying the velocity-field explanation.',fsq:'Scalar quantization as a discrete representation mechanism; quantization does not assign music-theory meaning to code IDs.',pitch:'An audio-to-MIDI transcription baseline. It is strongest with one instrument at a time; it is not a finished score-writing system.',mt3:'A research implementation for multitrack transcription into symbolic events.',xml:'Notation interchange: parts, measures, pitches, durations, voices, lyrics, and ties.',experiment:'Committed scripts, settings, lyrics, audio, transcription, and pinned model revisions for your actual take.'};const glossary=[['Sampling and frequency','A 48 kHz sample rate describes the time grid, not musical pitch. Pitch is related to periodicity; harmonics and timbre complicate its estimation.'],['Spectrogram / STFT','A windowed Fourier representation of energy across time and frequency. Window length trades temporal resolution against frequency resolution.'],['Fundamental and multipitch','F0 estimates a periodic source’s fundamental. Polyphonic transcription must identify multiple simultaneous notes, with overlapping harmonics and uncertain source assignment.'],['Note versus sounding duration','A symbolic note’s offset can differ from audible decay because of instrument sustain, pedal, reverberation, and articulation.'],['Acoustic latent','A continuous compressed audio representation learned by a waveform autoencoder.'],['Semantic / acoustic code','A discrete FSQ index at 5 Hz. “Semantic” does not imply a human-readable chord or note label.'],['Flow matching','Training a velocity field to transport one distribution toward another; inference numerically integrates that field.'],['DiT','A diffusion-style transformer backbone, here predicting velocities in acoustic latent space.'],['Classifier-free guidance','Combine conditional and null-condition predictions to increase conditioning influence. It is not a formal musical constraint.'],['Mask','A time-aligned signal specifying the region or task context for an edit. Acoustic boundaries can differ from mask boundaries.'],['Cross-attention','Acoustic queries retrieve information from encoded conditions. Inspectable attention weights do not alone establish causality.'],['Probe','A predictor trained to read an attribute from a representation. Accurate prediction does not prove the attribute can be changed independently.'],['Intermediate representation','A typed object between compiler passes, with explicit meaning, invariants, provenance, and transformation rules.'],['Performance versus score','Performance stores sounding time and expression; a score records musical structure and notation decisions.'],['SFT / distillation / LoRA','SFT fine-tunes behavior; distillation trains a short-step student; LoRA adapts weights through low-rank parameter updates.'],['Round-trip fidelity','Preservation of declared musical invariants across analysis, notation, performance, and rendering.']];return `${head('08','A map you can audit.','Primary sources, implementation boundaries, and the vocabulary needed to move between audio generation and symbolic music.')}<div class="grid-2"><section class="panel"><h3>Three evidence levels</h3><div class="concepts"><div class="concept"><h4>Documented implementation</h4><p>Mechanisms checked against pinned ACE-Step source and the saved local experiment.</p></div><div class="concept"><h4>Interactive illustration</h4><p>Synthetic matrices, code IDs, curves, and ODE sampling make the concepts visible. They are not outputs of ACE-Step.</p></div><div class="concept"><h4>Research proposal</h4><p>Symbolic adapters, score contracts, and latent intervention studies are proposed extensions. The working compiler is a small independent prototype.</p></div></div></section><section class="panel"><h3>Configuration provenance</h3><div class="code-panel"><pre>Code: ca1e85fe9430179831e6bc6be790c332190a3866\nDiT: acestep-v15-xl-base\nDiT snapshot:\n220c1166efbdd9583eafcb12eb160594bbfcb241\nShared model snapshot:\n19671f406d603126926c1b7e2adc169acbcade22\n\nVAE: stereo, 48,000 Hz, 64 latent channels\nRatios: [2, 4, 4, 6, 10]\nFSQ: [8, 8, 8, 5, 5, 5]\nPool window: 5 · DiT patch size: 2</pre></div><p class="note space-top">These concrete values come from the <a class="plain-link" href="${assetUrl('configuration-snapshot.json')}" target="_blank">captured model configuration</a> and the committed experiment record. Defaults in another implementation can differ.</p>${links(['experiment','config'])}</section></div><section class="reading-block"><h2>Read the system from its boundaries</h2>${Object.entries(A.sources).map(([k,v])=>`<article class="source-card"><h3><a href="${esc(v.url)}" target="_blank" rel="noopener">${esc(v.label)}</a></h3><p>${descriptions[k]}</p></article>`).join('')}<h2>Working glossary</h2><div class="term-grid">${glossary.map(([t,d])=>`<div class="term"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section>`;}
function clearFlow(){if(flowTimer)clearInterval(flowTimer);flowTimer=null;if($('#flow-play'))$('#flow-play').innerHTML=icon('play')+'Animate';}
function flowControlChange(){clearFlow();S.flow.step=0;updateFlow();}
function bind(){if(S.route==='pipeline'){$$('[data-stage]').forEach(b=>b.onclick=()=>{S.stage=Number(b.dataset.stage);location.hash=`pipeline/${S.stage}`;});$('#prev').onclick=()=>location.hash=`pipeline/${S.stage-1}`;$('#next').onclick=()=>location.hash=`pipeline/${S.stage+1}`;$$('[data-mode]').forEach(b=>b.onclick=()=>{S.mode=b.dataset.mode;if(S.mode!=='text2music')S.planner=false;else S.planner=true;shell();});$('#planner').onchange=e=>{S.planner=e.target.checked;shell();};$$('[data-tab]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.tab;shell();$('#tab-'+S.tab).focus({preventScroll:true});});}
if(S.route==='representations'){updateRepr();$('#duration').oninput=e=>{S.duration=Number(e.target.value);updateRepr();};$$('[data-repr]').forEach(b=>b.onclick=()=>{S.repr=b.dataset.repr;$$('[data-repr]').forEach(x=>x.setAttribute('aria-pressed',x===b));updateRepr();});}
if(S.route==='flow'){updateFlow();$('#flow-seed').onchange=e=>{S.flow.seed=Math.max(0,Math.min(4294967295,Number(e.target.value)||0));e.target.value=S.flow.seed;flowControlChange();};$('#flow-steps').onchange=e=>{S.flow.steps=Number(e.target.value);flowControlChange();};$('#solver').onchange=e=>{S.flow.solver=e.target.value;flowControlChange();};$('#guidance').oninput=e=>{S.flow.guidance=Number(e.target.value);flowControlChange();};$('#flow-task').onchange=e=>{S.flow.task=e.target.value;flowControlChange();};$('#turbo').onchange=e=>{clearFlow();S.flow.turbo=e.target.checked;S.flow.steps=S.flow.turbo?8:32;S.flow.guidance=1;S.flow.step=0;shell();};$('#flow-progress').oninput=e=>{clearFlow();S.flow.step=Number(e.target.value);updateFlow();};$('#flow-play').onclick=()=>{if(flowTimer){clearFlow();$('#flow-play').innerHTML=icon('play')+'Animate';return;}if(S.flow.step>=S.flow.steps)S.flow.step=0;$('#flow-play').innerHTML=icon('stop')+'Pause';flowTimer=setInterval(()=>{S.flow.step++;updateFlow();if(S.flow.step>=S.flow.steps){clearFlow();$('#flow-play').innerHTML=icon('play')+'Animate';}},Math.max(55,2300/S.flow.steps));};$('#flow-step').onclick=()=>{clearFlow();S.flow.step=Math.min(S.flow.steps,S.flow.step+1);updateFlow();};$('#flow-reset').onclick=()=>{flowControlChange();};}
if(S.route==='compiler'){compileUI();$('#compile').onclick=compileUI;$('#score-editor').oninput=()=>{stopNotes();S.score=$('#score-editor').value;S.compiled=null;$('#compile-status').className='info-line';$('#compile-status').textContent='Source changed. Compile again to update the output.';['score-play','export-midi','export-xml','transpose-up','transpose-down'].forEach(id=>$('#'+id).disabled=true);$('#score-view').innerHTML='<p class="note">Compile to render the edited source.</p>';$('#ir-output').textContent='Source changed; previous output invalidated.';};$('#score-example').onclick=()=>{$('#score-editor').value=initialScore;compileUI();};$('#transpose-up').onclick=()=>transpose(1);$('#transpose-down').onclick=()=>transpose(-1);$('#score-play').onclick=playNotes;$('#score-stop').onclick=stopNotes;$('#export-midi').onclick=exportMidi;$('#export-xml').onclick=exportXML;$$('[data-ir]').forEach(b=>b.onclick=()=>{S.irView=b.dataset.ir;$$('[data-ir]').forEach(x=>{x.setAttribute('aria-selected',x===b);x.tabIndex=x===b?0:-1;});$('#ir-output').setAttribute('aria-labelledby','ir-tab-'+S.irView);updateIR();});}
if(S.route==='training')$$('[data-training]').forEach(b=>b.onclick=()=>{S.training=b.dataset.training;shell();});
if(S.route==='experiment'){$('#trace-experiment').onclick=()=>{S.mode='lego';S.planner=false;S.stage=0;S.tab='intuition';};$$('audio').forEach(a=>a.onplay=()=>$$('audio').filter(x=>x!==a).forEach(x=>x.pause()));}
$$('[role=tablist]').forEach(list=>list.onkeydown=e=>{const tabs=Array.from(list.querySelectorAll('[role=tab]')),i=tabs.indexOf(document.activeElement);if(i<0||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();const id=tabs[n].id;if(id&&document.getElementById(id))document.getElementById(id).focus({preventScroll:true});});
}
window.addEventListener('hashchange',()=>{clearFlow();stopNotes();const next=routeFromHash();const routeChanged=next.route!==S.route;shell();if(routeChanged){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}});
shell();
